function itemVisual(item){return item.sprite?`<img class="item-sprite" src="${item.sprite}" alt="${item.name}">`:item.icon;}
const $=s=>document.querySelector(s),KEY='ilyuha-drop-v1';let state={balance:1337,inventory:[],opened:0,bonus:null},page='cases',busy=false;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Number.isFinite(s.balance)&&s.balance>=0&&Array.isArray(s.inventory))state={...state,...s};}catch{}
// Refresh saved loot artwork and replace the retired ice cream without changing item IDs.
for(const it of state.inventory){if(['Персонаж из лимбуса','перс из лимбуса','Перс из лимбуса'].includes(it.name))it.name='Лимбус';if(it.name==='Мороженое «Бр бр патапим 67»'){Object.assign(it,Game.getItems(Game.cases[0]).find(x=>x.name==='Зубная паста'));}else if(it.name==='Сырник'){it.sprite='assets/item-syrnik-plain.png';}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Хранилище недоступно: прогресс сохранится только до закрытия страницы');}sync();}
function sync(){$('#balance').textContent=state.balance.toLocaleString('ru');$('#count').textContent=state.inventory.length;const eligible=state.balance<100;for(const b of [$('#bonus'),$('#mobileBonus')]){if(!b)continue;b.disabled=!eligible;b.textContent=eligible?'+ 500 VPN · бесплатно':'500 VPN · при балансе ниже 100';}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function art(c){if(c.id==="cat"||c.id==="larp"||c.id==="tarkov")return `<div class="case-art real-art"><img class="standalone-case" src="assets/${c.id==='cat'?'cat-transparent':c.id==='larp'?'larp-cirno':c.id}.png" alt="${c.name}"></div>`;const regions={fat:[0,0,780,675,1536,1024],cat:[0,0,820,650,1536,1024],tongue:[0,0,945,875,1774,887]};const [x,y,w,h,iw,ih]=regions[c.id];return `<div class="case-art real-art" style="--accent:${c.color}"><div class="aura"></div><svg class="case-image" viewBox="${x} ${y} ${w} ${h}" role="img" aria-label="${c.name}" preserveAspectRatio="xMidYMid meet"><defs><clipPath id="clip-${c.id}"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath></defs><image href="assets/${c.id}.png" width="${iw}" height="${ih}" clip-path="url(#clip-${c.id})"/></svg></div>`;}
function render(){sync();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const main=$('#main');if(page==='cases'){main.innerHTML=`<section class="hero"><div><div class="eyebrow">МЕМНАЯ ЭКОНОМИКА / TELEGRAM MINI APP</div><h1>Большие сырники.<br><em>Длинный пайплайн.</em></h1><p>Илюха уже всё настроил. Выбирай кейс<br>и проверяй, что сегодня прилетит с прода.</p><button id="heroSpin" class="primary">Залететь в дроп <span>↗</span></button><small class="hero-note">ТОЛЬКО ВИРТУАЛЬНЫЕ VPN-КОИНЫ</small></div><div class="hero-portrait"><img src="assets/hero.png" alt="Илюха с сигарой и золотой VPN-монетой"></div></section><section class="case-section"><div class="section-title"><div><div class="eyebrow">ВЫБИРАЙ СВОЙ ВАЙБ</div><h2>Кейсы от Илюхи <sup>${(Game.cases.length+1).toString().padStart(2,"0")}</sup></h2></div><span>В каждом — немного абсурда ↙</span></div><div class="cards">${Game.cases.map((c,i)=>`<button class="case-card" data-case="${c.id}"><div class="card-meta"><span>CASE 0${i+1}</span><span>${['БАЗОВЫЙ','РЫЖИЙ ДРОП','ОСОБЫЙ','ЛАРП ДРОП','ЭВАКУАЦИЯ'][i]}</span></div>${art(c)}<h3>${c.name}</h3><p>${c.desc}</p><div class="card-bottom"><b><span class="mini-coin">V</span> ${c.price} VPN</b><span class="arrow">↗</span></div></button>`).join('')}<article class="case-card soon-card" aria-label="Следующий кейс — скоро"><div class="card-meta"><span>CASE ${(Game.cases.length+1).toString().padStart(2,"0")}</span><span>В РАЗРАБОТКЕ</span></div><div class="case-art real-art soon-art"><svg viewBox="0 0 320 250" aria-hidden="true"><path d="M40 70 235 40 285 80 285 195 92 230 40 190Z" fill="#050505"/><path d="M40 70 92 108 285 80M92 108V230M40 100 92 137 285 110" fill="none" stroke="#24221f" stroke-width="5"/><path d="M140 100V150H170V94M58 137V175M252 122V164" fill="none" stroke="#191817" stroke-width="9"/></svg><strong>СКОРО</strong></div><h3>Что-то намечается</h3><p>Илюха готовит новый дроп</p><div class="card-bottom"><b>Скоро откроется</b><span aria-hidden="true">⌛</span></div></article></div></section><section class="modes"><div><span class="eyebrow">ДАЛЬШЕ — БОЛЬШЕ</span><h2>Другие способы поймать дроп</h2></div><button data-goto="sbeu"><b>◈ СБЭУ</b><span>Режим в разработке ↗</span></button><button data-goto="upgrade"><b>↑ Апгрейд</b><span>Из хорошего в легендарное ↗</span></button></section>`;$('#heroSpin').onclick=()=>openCase('fat');main.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>openCase(b.dataset.case));}else if(page==='inventory'){main.innerHTML=`<div class="page-heading"><div class="eyebrow">ТВОЙ ЛУТ</div><h1>Инвентарь <em>/${state.inventory.length}</em></h1><p>Открыто кейсов: ${state.opened}. Обменивай предметы на игровые VPN.</p></div><div class="loot-grid">${state.inventory.length?state.inventory.map(it=>`<article class="loot ${it.rarity}"><span class="inventory-art">${itemVisual(it)}</span><h3>${it.name}</h3><button class="primary" data-sell="${it.id}">Обменять · ${it.value} VPN</button></article>`).join(''):'<div class="empty">▣<h2>Пока пусто, но это поправимо</h2><p>Открой первый кейс — предмет останется здесь.</p><button class="primary" data-goto="cases">К кейсам ↗</button></div>'}</div>`;main.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>sell(b.dataset.sell));}else{const up=page==='upgrade';main.innerHTML=`<div class="page-heading"><div class="eyebrow">НОВЫЙ РЕЖИМ / В РАЗРАБОТКЕ</div><h1>${up?'Апгрейд':'СБЭУ'} <em>скоро</em></h1><p>${up?'Один предмет. Одна цель. Шанс на что-то большее.':'Здесь появится отдельный игровой режим Илюхи.'}</p></div><section class="coming"><div class="coming-symbol">${up?'↑':'◈'}</div><h2>${up?'Прокачаем твой дроп':'Илюха готовит кое-что'}</h2><p>${up?'Выбор предмета из инвентаря → выбор цели → попытка улучшения. Правила и шансы появятся в следующей версии.':'Название уже на месте. Механика, правила и награды пока не определены.'}</p><div class="slots"><div>＋<span>${up?'Твой предмет':'Игровое поле'}</span></div><span>→</span><div>◇<span>${up?'Цель апгрейда':'Будущий результат'}</span></div></div><button disabled>Режим пока недоступен</button><small>Это макет. Монеты и предметы не списываются.</small></section>`;}main.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{page=b.dataset.goto;render();});}
function openCase(id){if(busy)return;const c=Game.cases.find(c=>c.id===id);$('#dialogContent').innerHTML=`<div class="eyebrow">СОДЕРЖИМОЕ КЕЙСА</div><h2>${c.name}</h2><button type="button" class="speed-button ${CaseReel.fast?'enabled':''}" id="caseFast" aria-pressed="${CaseReel.fast}">⚡ Быстро ×2 <span>${CaseReel.fast?'ВКЛ':'ВЫКЛ'}</span></button>${art(c)}<div class="odds">${Game.getItems(c).map((it,i)=>`<div class="${it.rarity}"><span class="odds-item">${itemVisual(it)} <span>${it.name}</span></span><b>${c.weights[i]}%</b><small>${it.value} VPN</small></div>`).join('')}</div><p class="fine">Один случайный предмет за открытие. Обменная стоимость может быть ниже цены кейса.</p><button class="primary wide" id="spin" ${state.balance<c.price?'disabled':''}>${state.balance<c.price?'Не хватает VPN':`Открыть за ${c.price} VPN`}</button>`;$('#caseDialog').showModal();$('#caseFast').onclick=()=>{CaseReel.setFast(!CaseReel.fast);const b=$('#caseFast');b.setAttribute('aria-pressed',String(CaseReel.fast));b.classList.toggle('enabled',CaseReel.fast);b.innerHTML=`⚡ Быстро ×2 <span>${CaseReel.fast?'ВКЛ':'ВЫКЛ'}</span>`;};$('#spin').onclick=()=>spin(c);}
function spin(c){if(busy||state.balance<c.price)return;busy=true;state.balance-=c.price;const item={...Game.pick(c),id:crypto.randomUUID()};if(item.type==='currency')state.balance+=item.value;else state.inventory.push(item);state.opened++;save();$('#caseDialog .close').disabled=true;$('#dialogContent').innerHTML=`<div class="eyebrow">ПАЙПЛАЙН ЗАПУЩЕН</div><h2>Илюха проверяет дроп…</h2>${CaseReel.markup(c,item)}`;CaseReel.animate();setTimeout(()=>{busy=false;$('#caseDialog .close').disabled=false;$('#dialogContent').innerHTML=`<div class="eyebrow">НУ ЭТО ПРОД!</div><div class="reward ${item.rarity}">${itemVisual(item)}</div><h2>${item.name}</h2><p>${item.type==='currency'?'Монеты уже зачислены на баланс':`Предмет уже в инвентаре · ${item.value} VPN`}</p>${item.type==='currency'?'':`<button class="primary wide" id="sellReward">Обменять на ${item.value} VPN</button>`}<button class="primary wide" id="spinAgain" ${state.balance<c.price?'disabled':''}>${state.balance<c.price?'Не хватает VPN':`Крутить снова · ${c.price} VPN`}</button><button class="subtle wide" id="keepReward">${item.type==='currency'?'Отлично':'Оставить в инвентаре'}</button>`;$('#spinAgain').onclick=()=>spin(c);if($('#sellReward'))$('#sellReward').onclick=()=>{sell(item.id);$('#caseDialog').close();};$('#keepReward').onclick=()=>{$('#caseDialog').close();render();};},CaseReel.fast?2250:4500);}
function sell(id){const idx=state.inventory.findIndex(i=>i.id===id);if(idx<0)return;const [it]=state.inventory.splice(idx,1);state.balance+=it.value;save();render();toast(`+${it.value} VPN · ${it.name}`);}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();});$('#caseDialog .close').onclick=()=>{if(!busy)$('#caseDialog').close();};$('#caseDialog').addEventListener('cancel',e=>{if(busy)e.preventDefault();});$('#bonus').onclick=()=>{if(state.balance>=100){toast('Бесплатные 500 VPN доступны, когда баланс ниже 100');return;}state.balance+=500;save();toast('+500 VPN бесплатно. Продолжаем!');};render();





